from sklearn.linear_model import GeneralizedLinearRegressor
from joblib import dump

class GLMTrainer:
    def __init__(self):
        self.model = GeneralizedLinearRegressor()

    def train(self, X, y, exposure=None):
        if exposure is not None:
            self.model.fit(X, y, sample_weight=exposure)
        else:
            self.model.fit(X, y)

    def predict(self, X):
        return self.model.predict(X)

    def save(self, path):
        """Save the trained model."""
        if self.model:
            dump(self.model, path)
        else:
            raise ValueError("No trained model to save.")

